module convolutional_encoder (  
    input clk,  
    input reset,  
    input [3:0] data_in,  
    output reg [7:0] encoded_out  
);  
    reg [2:0] shift_reg;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shift_reg <= 3'b000;  
            encoded_out <= 8'b00000000;  
        end else begin  
            encoded_out <= 8'b00000000;  
            for (i = 0; i < 4; i = i + 1) begin  
                shift_reg = {data_in[i], shift_reg[2:1]};  
                encoded_out[2*i] = shift_reg[0] ^ shift_reg[1] ^ shift_reg[2]; // g1 = 111  
                encoded_out[2*i + 1] = shift_reg[0] ^ shift_reg[2]; // g2 = 101  
            end  
        end  
    end  
endmodule

