    uart_transmitter dut (
        .baud_tick(baud_tick),
        .clk(clk),
        .data_in(data_in),
        .rst_n(rst_n),
        .start(start),
        .stop(stop),
        .tx(tx)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst_n = 1'b0;
            baud_tick = 1'b0;
            start = 1'b0;
            data_in = 8'h00;
            stop = 1'b1;
            repeat(5) @(posedge clk);
            rst_n = 1'b1;
            repeat(5) @(posedge clk);
        end
        endtask
    task run_uart_transaction;

        input [7:0] send_data;
        input send_stop;
        reg [9:0] captured_frame;
        reg [9:0] expected_frame;
        integer i;
        begin
            test_num = test_num + 1;
            $display("\n--- Test Case %0d: Sending Data 0x%h ---", test_num, send_data);


            data_in = send_data;
            stop = send_stop;


            @(posedge clk);
            start = 1'b1;
            @(posedge clk);
            start = 1'b0;



            for (i = 0; i < 10; i = i + 1) begin
                #1;
                captured_frame[i] = tx;


                baud_tick = 1'b1;
                @(posedge clk);
                baud_tick = 1'b0;


                repeat(4) @(posedge clk);
            end



            expected_frame[0] = 1'b0;
            expected_frame[8:1] = send_data;
            expected_frame[9] = send_stop;


            if (captured_frame === expected_frame) begin
                $display("  Success: Frame %b matches expected.", captured_frame);
                #1;

                check_outputs(tx);
            end else begin
                $display("  Error: Frame %b != Expected %b", captured_frame, expected_frame);
                #1;

                check_outputs(~tx);
            end
        end
        endtask

