            run_uart_transaction(8'hA5, 1'b1);
        end
        endtask

    task testcase006;

        begin
            reset_dut();
            run_uart_transaction(8'h3C, 1'b0);
        end
        endtask

    task testcase007;

        begin
            reset_dut();
            run_uart_transaction(8'h81, 1'b1);
        end
        endtask

    // Test stimulus
    initial begin
