code:
module pulse_generator (
    input wire clk,
    input wire reset,
    output reg pulse
);
    reg [2:0] state; // 3-bit state to count clock cycles

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 3'b000;
            pulse <= 1'b0;
        end else begin
            if (state < 3'b101) begin // First 5 cycles (0 to 4)
                pulse <= 1'b1;
                state <= state + 1;
            end else if (state < 3'b111) begin // Next 3 cycles (5 to 7)
                pulse <= 1'b0;
                state <= state + 1;
            end else begin
                state <= 3'b000; // Reset to the initial state after 8 cycles
            end
        end
    end
endmodule

