module simple_des (  
    input [63:0] data_in,  
    input [63:0] key,  
    input clk,  
    input rst,  
    output reg [63:0] data_out  
);  

    reg [63:0] temp_data;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            data_out <= 64'b0;  
        end else begin  
            // Simplified encryption process: XOR with the key  
            temp_data <= data_in ^ key;  
            data_out <= temp_data;  
        end  
    end  
endmodule

