module aes_8bit (  
    input wire clk,  
    input wire rst,  
    input wire [7:0] plaintext,  
    input wire [7:0] key,  
    output reg [7:0] ciphertext  
);  

    // S-Box for SubBytes step (example values)
    reg [7:0] s_box [0:255];  
    initial begin  
        s_box[0] = 8'h63;  
        s_box[1] = 8'h7c;  
        s_box[2] = 8'h77;  
        // ... (initialize the rest of the S-Box here)  
        s_box[255] = 8'h00;  
    end  

    reg [7:0] state;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            ciphertext <= 8'b0;  
            state <= 8'b0;  
        end else begin  
            // SubBytes step  
            state <= s_box[plaintext];  
            // ShiftRows step (no shift for 8 bits)  
            // MixColumns step (simple XOR with key for the example)  
            ciphertext <= state ^ key;  
        end  
    end  
endmodule

