module watchdog_timer(
    input clk,
    input reset,
    input [3:0] timeout,
    output reg expired
);
    reg [3:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 4'b0000;
            expired <= 1'b0;
        end else begin
            if (count < timeout) begin
                count <= count + 1;
                expired <= 1'b0;
            end else begin
                expired <= 1'b1;
            end
        end
    end
endmodule

