module kalman_filter (  
    input clk,  
    input reset,  
    input [15:0] measurement,  
    output reg [15:0] estimate  
);  
    reg [15:0] k_gain;  
    reg [15:0] prev_estimate;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            estimate <= 16'b0;  
            prev_estimate <= 16'b0;  
            k_gain <= 16'h1;  
        end else begin  
            // Prediction step  
            prev_estimate <= estimate;  
            estimate <= prev_estimate + k_gain * (measurement - prev_estimate);  
            // Update Kalman gain (simple fixed value for demo purposes)  
            k_gain <= 16'h2;  
        end  
    end  
endmodule

