module dijkstra #(parameter V = 5) (  
    input [V*V-1:0] adj_matrix,  // Adjacency matrix  
    input [2:0] src,              // Source vertex (3 bits for 0 to 4)  
    output reg [V-1:0] dist       // Shortest distances  
);  
    integer i, j;  
    reg [V-1:0] visited;  
    reg [V-1:0] temp_dist;  
    reg [3:0] min_idx;  
    reg [31:0] min_val;  

    initial begin  
        dist = {V{1'b1}};  // Initialize distances to infinity (or a large number)  
        visited = 0;  
        dist[src] = 0;     // Distance from source to itself is 0  
    end  

    always @(*) begin  
        for (i = 0; i < V; i = i + 1) begin  
            min_val = 32'hFFFFFFFF;  
            min_idx = 4'b1111;  
            for (j = 0; j < V; j = j + 1) begin  
                if (!visited[j] && dist[j] < min_val) begin  
                    min_val = dist[j];  
                    min_idx = j;  
                end  
            end  
            if (min_idx < V) begin  
                visited[min_idx] = 1;  
                for (j = 0; j < V; j = j + 1) begin  
                    if (adj_matrix[min_idx * V + j] > 0 && !visited[j]) begin  
                        temp_dist[j] = dist[min_idx] + adj_matrix[min_idx * V + j];  
                        if (temp_dist[j] < dist[j]) begin  
                            dist[j] = temp_dist[j];  
                        end  
                    end  
                end  
            end  
        end  
    end  
endmodule

