module encoder_4to2(
    input wire I3, I2, I1, I0,
    output reg O1, O0,
    output reg valid
);

always @(*) begin
    valid = 1'b0;
    O1 = 1'bx;
    O0 = 1'bx;

    if (I3) begin
        O1 = 1'b1;
        O0 = 1'b1;
        valid = 1'b1;
    end
    else if (I2) begin
        O1 = 1'b1;
        O0 = 1'b0;
        valid = 1'b1;
    end
    else if (I1) begin
        O1 = 1'b0;
        O0 = 1'b1;
        valid = 1'b1;
    end
    else if (I0) begin
        O1 = 1'b0;
        O0 = 1'b0;
        valid = 1'b1;
    end
end
endmodule

