module crc_generator (  
    input [3:0] data_in,  
    input clk,  
    input reset,  
    output reg [3:0] crc_out  
);  
    reg [3:0] crc;  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            crc <= 4'b0000;  
        end else begin  
            crc <= crc ^ data_in;  
            for (i = 0; i < 4; i = i + 1) begin  
                if (crc[3]) begin  
                    crc <= {crc[2:0], 1'b0} ^ 4'b1011; // x^4 + x + 1 (11011)  
                end else begin  
                    crc <= {crc[2:0], 1'b0};  
                end  
            end  
            crc_out <= crc;  
        end  
    end  
endmodule

module bfs (  
    input clk,  
    input rst,  
    input [3:0] start_node,  
    output reg [15:0] visited_nodes  
);  
    reg [15:0] adjacency_matrix [0:15];  
    reg [15:0] queue;  
    reg [3:0] front, back;  
    reg [15:0] visited;  
    integer i;  

    initial begin  
        // Initialize adjacency matrix (example graph)  
        adjacency_matrix[0] = 16'b0000000000000011; // Node 0 connected to Node 1 and Node 2  
        adjacency_matrix[1] = 16'b0000000000000100; // Node 1 connected to Node 3  
        adjacency_matrix[2] = 16'b0000000000000100; // Node 2 connected to Node 3  
        adjacency_matrix[3] = 16'b0000000000000000; // Node 3 connected to no one  
        // ... initialize other nodes as needed  
    end  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            visited_nodes <= 16'b0;  
            queue <= 16'b0;  
            front <= 0;  
            back <= 0;  
            visited <= 16'b0;  
        end else begin  
            if (front < back) begin  
                visited_nodes <= visited_nodes | (1 << queue[front]);  
                visited[queue[front]] <= 1;  
                front <= front + 1;  

                for (i = 0; i < 16; i = i + 1) begin  
                    if (adjacency_matrix[queue[front]][i] && !visited[i]) begin  
                        queue[back] <= i;  
                        back <= back + 1;  
                    end  
                end  
            end else if (front == 0) begin  
                queue[back] <= start_node;  
                back <= back + 1;  
            end  
        end  
    end  
endmodule

module uart_transmitter(
    input wire clk,
    input wire reset,
    input wire start,
    input wire [7:0] data_in,
    output reg tx,
    output reg ready
);
    parameter BAUD_RATE = 9600;
    localparam CLOCK_FREQ = 50000000; // 50 MHz
    localparam CYCLES_PER_BIT = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] state;
    reg [7:0] data_buffer;
    reg [15:0] bit_count;

    localparam IDLE = 0, START_BIT = 1, DATA_BITS = 2, STOP_BIT = 3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            tx <= 1;
            ready <= 1;
            bit_count <= 0;
        end else begin
            case (state)
                IDLE: begin
                    ready <= 1;
                    if (start) begin
                        data_buffer <= data_in;
                        state <= START_BIT;
                        bit_count <= 0;
                        ready <= 0;
                    end
                end
                START_BIT: begin
                    tx <= 0; // Start bit
                    if (bit_count < CYCLES_PER_BIT - 1) begin
                        bit_count <= bit_count + 1;
                    end else begin
                        bit_count <= 0;
                        state <= DATA_BITS;
                    end
                end
                DATA_BITS: begin
                    tx <= data_buffer[bit_count]; // Transmit data bits
                    if (bit_count < 7) begin
                        bit_count <= bit_count + 1;
                    end else begin
                        bit_count <= 0;
                        state <= STOP_BIT;
                    end
                end
                STOP_BIT: begin
                    tx <= 1; // Stop bit
                    if (bit_count < CYCLES_PER_BIT - 1) begin
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= IDLE;
                        ready <= 1;
                    end
                end
            endcase
        end
    end
endmodule

module jpeg_dct(input [3:0] pixel0, input [3:0] pixel1, input [3:0] pixel2, input [3:0] pixel3,  
                output reg [15:0] dct_out);  

    always @(*) begin  
        // Simplified DCT transformation:  
        dct_out = (pixel0 + pixel1 + pixel2 + pixel3) * 4;  
    end  
endmodule

module dfs_tree (
    input clk,
    input reset,
    input [7:0] node_value,
    input push,
    input pop,
    output reg [7:0] visited_node,
    output reg done
);

    reg [7:0] stack [0:15];
    reg [3:0] sp;  // Stack pointer

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sp <= 0;
            done <= 0;
            visited_node <= 0;
        end else begin
            if (push && sp < 16) begin
                stack[sp] <= node_value;
                sp <= sp + 1;
            end

            if (pop && sp > 0) begin
                sp <= sp - 1;
                visited_node <= stack[sp];
                done <= 1;
            end else begin
                done <= 0;
            end
        end
    end
endmodule

module divider_8bit(  
    input [7:0] dividend,  
    input [7:0] divisor,  
    input clk,  
    input reset,  
    output reg [2:0] quotient,  
    output reg [4:0] remainder,  
    output reg done  
);  
    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            quotient <= 0;  
            remainder <= 0;  
            done <= 0;  
        end else begin  
            if (divisor != 0) begin  
                quotient <= dividend / divisor;  
                remainder <= dividend % divisor;  
                done <= 1;  
            end else begin  
                quotient <= 0;  
                remainder <= 0;  
                done <= 1;  
            end  
        end  
    end  
endmodule

