module decoder_2to4 (
    input wire A1,
    input wire A0,
    output reg [3:0] Y
);
    always @(*) begin
        // Initialize outputs to 0
        Y = 4'b0000;

        // Hazard detection and resolution
        case ({A1, A0})
            2'b00: Y = 4'b0001; // Y0 active
            2'b01: Y = 4'b0010; // Y1 active
            2'b10: Y = 4'b0100; // Y2 active
            2'b11: Y = 4'b1000; // Y3 active
            default: Y = 4'b0000;
        endcase
    end
endmodule

