module uart_transmitter(  
    input clk,  
    input rst,  
    input [7:0] data_in,  
    input send,  
    output reg tx,  
    output reg ready  
);  
    parameter BAUD_RATE = 9600;  
    parameter CLOCK_FREQ = 50000000;  
    parameter BIT_TIME = CLOCK_FREQ / BAUD_RATE;  
    reg [3:0] state;  
    reg [7:0] shift_reg;  
    reg [15:0] bit_counter;  

    localparam IDLE = 4'b0000,  
               START_BIT = 4'b0001,  
               DATA_BITS = 4'b0010,  
               STOP_BIT = 4'b0011;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            tx <= 1;  
            ready <= 1;  
            bit_counter <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (send) begin  
                        shift_reg <= data_in;  
                        tx <= 0;  // Start bit  
                        state <= START_BIT;  
                        ready <= 0;  
                        bit_counter <= 0;  
                    end  
                end  
                START_BIT: begin  
                    if (bit_counter < BIT_TIME - 1)  
                        bit_counter <= bit_counter + 1;  
                    else begin  
                        bit_counter <= 0;  
                        state <= DATA_BITS;  
                    end  
                end  
                DATA_BITS: begin  
                    if (bit_counter < BIT_TIME - 1)  
                        bit_counter <= bit_counter + 1;  
                    else begin  
                        bit_counter <= 0;  
                        tx <= shift_reg[0];  
                        shift_reg <= {1'b0, shift_reg[7:1]};  
                        if (shift_reg == 0) begin  
                            state <= STOP_BIT;  
                        end  
                    end  
                end  
                STOP_BIT: begin  
                    if (bit_counter < BIT_TIME - 1)  
                        bit_counter <= bit_counter + 1;  
                    else begin  
                        tx <= 1;  // Stop bit  
                        state <= IDLE;  
                        ready <= 1;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

