module adaptive_lms_filter (
    input clk,
    input rst,
    input signed [15:0] x_in,        // Input signal
    input signed [15:0] d_in,        // Desired signal
    output signed [15:0] y_out       // Output signal
);
    parameter N = 5;                 // Number of filter taps
    parameter mu = 16'h0001;         // Step size (learning rate)

    reg signed [15:0] w [0:N-1];     // Filter coefficients
    reg signed [15:0] x [0:N-1];     // Input samples
    reg signed [15:0] y;              // Filtered output
    reg signed [15:0] error;          // Error signal

    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Reset coefficients and states
            for (i = 0; i < N; i = i + 1) begin
                w[i] <= 16'sd0;
                x[i] <= 16'sd0;
            end
            y <= 16'sd0;
        end else begin
            // Shift input samples
            for (i = N-1; i > 0; i = i - 1) begin
                x[i] <= x[i-1];
            end
            x[0] <= x_in;

            // Calculate output
            y = 16'sd0;
            for (i = 0; i < N; i = i + 1) begin
                y = y + (w[i] * x[i]);
            end

            // Calculate error
            error = d_in - y;

            // Update coefficients
            for (i = 0; i < N; i = i + 1) begin
                w[i] = w[i] + (mu * error * x[i]) >>> 15; // Shift right for scaling
            end
        end
    end

    assign y_out = y;
endmodule

