module watchdog_timer (
    input wire clk,
    input wire rst,
    input wire feed,
    output reg reset
);
    parameter TIMEOUT = 8'd100; // Timeout period in clock cycles
    reg [7:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 8'b0;
            reset <= 1'b0;
        end else if (feed) begin
            counter <= 8'b0;
            reset <= 1'b0;
        end else begin
            if (counter < TIMEOUT - 1) begin
                counter <= counter + 1;
                reset <= 1'b0;
            end else begin
                reset <= 1'b1; // Trigger reset
            end
        end
    end
endmodule

