module kalman_filter #(parameter STATE_WIDTH = 16, parameter MEASUREMENT_WIDTH = 16)  
(  
    input clk,  
    input rst,  
    input signed [MEASUREMENT_WIDTH-1:0] measurement,  
    input signed [STATE_WIDTH-1:0] prev_estimate,  
    input signed [STATE_WIDTH-1:0] process_noise,  
    input signed [STATE_WIDTH-1:0] measurement_noise,  
    output reg signed [STATE_WIDTH-1:0] new_estimate  
);  

    reg signed [STATE_WIDTH-1:0] kalman_gain;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            new_estimate <= 0;  
            kalman_gain <= 0;  
        end else begin  
            kalman_gain <= process_noise / (process_noise + measurement_noise);  
            new_estimate <= prev_estimate + kalman_gain * (measurement - prev_estimate);  
        end  
    end  
endmodule

module rising_edge_detector (
    input wire clk,
    input wire rst,
    input wire signal_in,
    output reg signal_out
);

reg signal_in_prev;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        signal_in_prev <= 0;
        signal_out <= 0;
    end else begin
        signal_out <= (signal_in && !signal_in_prev);
        signal_in_prev <= signal_in;
    end
end

endmodule

